import unittest
from candidate import filter_by_substring

class TestFilterBySubstring(unittest.TestCase):
    def test_filter_by_substring_empty_list(self):
        self.assertEqual(filter_by_substring([], 'a'), [])

    def test_filter_by_substring_with_matches(self):
        self.assertEqual(filter_by_substring(['abc', 'bacd', 'cde', 'array'], 'a'), ['abc', 'bacd', 'array'])

    def test_filter_by_substring_without_matches(self):
        self.assertEqual(filter_by_substring(['abc', 'bacd', 'cde', 'array'], 'z'), [])

    def test_filter_by_substring_with_empty_string(self):
        self.assertEqual(filter_by_substring(['abc', 'bacd', 'cde', 'array'], ''), ['abc', 'bacd', 'cde', 'array'])

    def test_filter_by_substring_with_none_substring(self):
        with self.assertRaises(TypeError):
            filter_by_substring(['abc', 'bacd', 'cde', 'array'], None)

    def test_filter_by_substring_with_none_list(self):
        with self.assertRaises(TypeError):
            filter_by_substring(None, 'a')

    def test_filter_by_substring_with_non_string_substring(self):
        with self.assertRaises(TypeError):
            filter_by_substring(['abc', 'bacd', 'cde', 'array'], 123)

    def test_filter_by_substring_with_non_list_input(self):
        with self.assertRaises(TypeError):
            filter_by_substring('abc', 'a')

if __name__ == '__main__':
    unittest.main()
